INSERT INTO public.categories (id, name, slug, description) VALUES
  ('11111111-1111-1111-1111-111111111101', '의류', 'apparel', '차차 캐릭터가 담긴 편안하고 트렌디한 캠퍼스 웨어'),
  ('11111111-1111-1111-1111-111111111102', '문구', 'stationery', '강의실과 도서관에서 함께하는 귀여운 차차 문구류'),
  ('11111111-1111-1111-1111-111111111103', '잡화', 'accessories', '일상 곳곳에 포인트를 더해주는 실용적인 데일리 굿즈'),
  ('11111111-1111-1111-1111-111111111104', '한정판', 'limited', '오직 정해진 시즌과 수량으로만 만날 수 있는 스페셜 에디션')
INSERT INTO public.products (name, sku, category_id, description, price, sale_price, stock, image_url, is_limited, status, total_sold) VALUES
  ('차차 후드티', 'CNU-APP-001', '11111111-1111-1111-1111-111111111101', '충남대학교 시그니처 네이비 컬러에 귀여운 차차 자수가 새겨진 프리미엄 헤비웨이트 오핏 후드티입니다.', 59000, 49000, 45, '/images/products/default-product.svg', false, 'on_sale', 142),
  ('차차 양말', 'CNU-APP-002', '11111111-1111-1111-1111-111111111101', '발목 부분에 앙증맞은 차차 포인트 자수가 들어간 사계절 코마사 데일리 양말입니다.', 7000, 5900, 120, '/images/products/default-product.svg', false, 'on_sale', 215),
  ('차차 메모지', 'CNU-STA-001', '11111111-1111-1111-1111-111111111102', '전공 필기와 할 일 정리에 딱 좋은 100매 구성의 고평량 차차 떡메모지입니다.', 4500, 4000, 85, '/images/products/default-product.svg', false, 'on_sale', 189),
  ('맥세이프 그립톡', 'CNU-ACC-001', '11111111-1111-1111-1111-111111111103', '강력한 네오디뮴 자석으로 탈부착이 자유로운 아크릴 차차 맥세이프 스마트톡입니다.', 18000, 15900, 60, '/images/products/default-product.svg', false, 'on_sale', 164),
  ('말랑 PVC 키링', 'CNU-ACC-002', '11111111-1111-1111-1111-111111111103', '에어팟과 백팩에 달기 좋은 입체감 있는 말랑말랑 차차 PVC 키링입니다.', 9500, 8500, 95, '/images/products/default-product.svg', false, 'on_sale', 230),
  ('차차 텀블러', 'CNU-ACC-003', '11111111-1111-1111-1111-111111111103', '도서관 밤샘 공부 필수템! 보온/보냉이 뛰어난 500ml 스테인리스 차차 텀블러입니다.', 28000, 24000, 40, '/images/products/default-product.svg', false, 'on_sale', 118),
  ('랜덤 피규어', 'CNU-ACC-004', '11111111-1111-1111-1111-111111111103', '6가지 캠퍼스 라이프 콘셉트 중 1종이 랜덤으로 들어있는 차차 미니 피규어 블라인드 박스입니다.', 15000, null, 32, '/images/products/default-product.svg', false, 'on_sale', 96),
  ('노트북 파우치', 'CNU-ACC-005', '11111111-1111-1111-1111-111111111103', '푹신한 극세사 안감으로 노트북과 아이패드를 안전하게 보호하는 차차 퀼팅 파우치입니다.', 32000, 28900, 28, '/images/products/default-product.svg', false, 'on_sale', 87),
  ('보조배터리', 'CNU-ACC-006', '11111111-1111-1111-1111-111111111103', '10000mAh 대용량에 PD 고속충전을 지원하는 포켓 사이즈 차차 보조배터리입니다.', 35000, 31500, 18, '/images/products/default-product.svg', false, 'on_sale', 64),
  ('양치도구 세트', 'CNU-ACC-007', '11111111-1111-1111-1111-111111111103', '차차 UV 살균 케이스와 칫솔, 미니 치약으로 구성된 휴대용 캠퍼스 양치 세트입니다.', 14000, 12000, 50, '/images/products/default-product.svg', false, 'on_sale', 73),
  ('여행용 파우치 세트', 'CNU-ACC-008', '11111111-1111-1111-1111-111111111103', 'MT, 학회, 방학 여행 짐 정리를 깔끔하게 도와주는 3종 메쉬 차차 파우치 세트입니다.', 24000, 19900, 35, '/images/products/default-product.svg', false, 'on_sale', 52),
  ('차량 방향제', 'CNU-ACC-009', '11111111-1111-1111-1111-111111111103', '송풍구에 꽂으면 은은한 코튼블로썸 향이 퍼지는 귀여운 차차 피규어 방향제입니다.', 16000, 13900, 42, '/images/products/default-product.svg', false, 'on_sale', 48),
  ('에코백', 'CNU-ACC-010', '11111111-1111-1111-1111-111111111103', '전공 서적과 16인치 노트북도 거뜬히 들어가는 탄탄한 10수 캔버스 차차 에코백입니다.', 22000, 18500, 65, '/images/products/default-product.svg', false, 'on_sale', 134),
  ('커스텀 의상 차차 인형', 'CNU-LIM-001', '11111111-1111-1111-1111-111111111104', '[한정판] 과잠바, 학사모, 응원복 등 의상을 자유롭게 갈아입힐 수 있는 25cm 차차 스페셜 인형입니다.', 42000, 38000, 15, '/images/products/default-product.svg', true, 'on_sale', 85),
  ('시즌 한정 차차 인형', 'CNU-LIM-002', '11111111-1111-1111-1111-111111111104', '[한정판] 벚꽃 시즌 & 대동제 기념 스페셜 케이프를 착용한 리미티드 에디션 차차 봉제인형입니다.', 38000, 34000, 8, '/images/products/default-product.svg', true, 'on_sale', 92),
  ('시즌 한정 스티커', 'CNU-LIM-003', '11111111-1111-1111-1111-111111111104', '[한정판] 홀로그램 코팅이 적용된 문구/한정판 겸용 차차 리무버블 스티커 팩입니다.', 6500, 5500, 25, '/images/products/default-product.svg', true, 'on_sale', 175)
